 files.append({'path':'png/'+p.name,'character':v.split('-')[0],'pose':'side-facing-right' if '-side' in v else 'solo-bed-oblique','frame':int(n),'anchor':{'kind':'body-center','position':A[v]},'pillowHeadReference':H[v],'sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'unchangedApproved180':v=='somang-sleep' and n=='0'})
