m={'revision':187,'action':'sleep','status':'awaiting-user-review','artApproved':False,'runtimeEligible':False,'runtimeOwner':'opus','canvas':[620,720],'referenceVisibleHeight':576,'frameCount':10,'newOrModifiedCount':9,'unchangedApprovedCount':1,'files':files,'playback':{'sequence':[0,1],'durationMs':[800,800],'loop':True},'replacesUnapproved':'../sleep-trio-v184/','approvedReference':'../sleep-somang-v180/png/somang-sleep-0.png','approvedReferenceModified':False,'poseGuide':'../pose-guides/','skinReference':'../final/<character>/idle + walk; front for solo, right for right-facing side; Somang180 original colors retained','soloPoses':{'set':'screen-left arm behind head, screen-right arm lowered on abdomen; diagonal overhead-oblique lying plane','horus':'hands on abdomen, diagonal overhead-oblique lying plane','somang':'approved180 frame0 unchanged; inhalation1 only replaced'},'pairedPoses':{'set':'faces right toward Somang, lower arm under head, upper arm loose in front, hair flows over pillow and behind back','horus':'faces right toward Somang, hands together in front, knees slightly bent'},'breathing':{'torsoShoulderArmHairRisePx':8,'torsoWidthExpansionPxPerSideMax':6,'headEyeTranslationPx':[0,-1],'closedEyeDrawing':'same pixel pattern in both frames, translated1px with head','pillowHair':'fixed','feet':'fixed','hairOverShoulders':'moves in the same field as shoulder/chest; lower tips move'},'bedReferenceScale':160/576,'gamePreviewScale':31/576,'bedReferences':['../../map-expansion/set-room-v6-single-window-day.png','../../map-expansion/horus-room-v2-wide-day.png'],'effectPolicy':'No bed, pillow, quilt, cast shadow or effects in character PNG; game handles quilt occlusion.','checks':{'skin':'10/10 같음','head':'action-check cannot match Set/Horus rotated sleeping heads (x2.0+ invalid); Somang approved180 itself measures1.25; do not resize approved head to force this metric. Same-scale idle-front / both sleep frames / Somang180 comparison visually inspected.','actionInput':'Filename aliases are byte-identical copies; mapping in checks/action-input-map.json because checker regex ignores sleep filenames.','game31':'Decoded shared-palette GIF compared at31px idle scale and enlarged; chest/arm/lower hair changes remain, pillow and feet stay anchored.','pairOverlap':'0 opaque overlap pixels in both frames on both actual room beds.'},'visualReview':['소망180의 대각선 누운 시점·머리 베개 자리·짧아진 몸을 기준으로 비교','정지 정면과 같은 배율로 얼굴·머리 크기 확인; 누운 몸 길이는 머리를 줄이지 않고 조정','화면 오른쪽 세트 팔을 내리고 옆잠의 위쪽 팔도 몸 앞으로 내림','목·어깨·팔·몸통·머리 끝을 밝고 어두운 배경에서 두 프레임 확대 비교','31px GIF의 실제 저장 프레임을 비교해 머리 전체의 흔들림 없이 호흡부 변화 확인','같이 자기에서 양쪽 베개를 향한 머리와 마주 보는 얼굴·침대 안 위치 및 두 프레임 겹침 확인']}
